/**
 * Billing period arithmetic: where a period ends, what a full period costs and
 * what a change made part-way through a period is charged.
 *
 * Pure functions over `Date`, all in UTC. Callers own persistence and events.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export interface PeriodSpan {
  readonly start: Date;
  readonly end: Date;
}

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Adds whole calendar months, keeping the day and time of day. When the target
 * month has no such day the result is that month's last day (31 Jan → 28 Feb),
 * so a later step from the clamped date carries the clamp forward.
 */
export function addMonths(from: Date, months: number): Date {
  const year = from.getUTCFullYear();
  const monthIndex = from.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
  const day = Math.min(from.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      monthIndex,
      day,
      from.getUTCHours(),
      from.getUTCMinutes(),
      from.getUTCSeconds(),
      from.getUTCMilliseconds(),
    ),
  );
}

/** The period that starts at `start` and runs for one billing interval. */
export function periodFrom(start: Date, interval: BillingInterval): PeriodSpan {
  return { start, end: addMonths(start, monthsIn(interval)) };
}

/** Price of `seats` seats for `months` months on `plan`, in cents. */
export function fullChargeCents(
  plan: PlanId,
  seats: number,
  months: number,
): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * months;
}

/** Whole days in a period, rounded and never less than one. */
export function daysInPeriod(period: PeriodSpan): number {
  const days = Math.round(
    (period.end.getTime() - period.start.getTime()) / MS_PER_DAY,
  );
  return Math.max(1, days);
}

/** Whole or started days from `now` to the period end; zero once it has passed. */
export function daysLeftInPeriod(period: PeriodSpan, now: Date): number {
  const remaining = period.end.getTime() - now.getTime();
  if (remaining <= 0) return 0;
  return Math.ceil(remaining / MS_PER_DAY);
}

/**
 * The share of a full-period amount that falls after `now`: scaled by the days
 * left over the days in the period, rounded down to whole cents.
 */
export function prorateCents(
  fullAmountCents: number,
  period: PeriodSpan,
  now: Date,
): number {
  const total = daysInPeriod(period);
  const left = Math.min(daysLeftInPeriod(period, now), total);
  return Math.floor((fullAmountCents * left) / total);
}

