/** The columns a billing change may write; anything omitted stays as it was. */
export type SubscriptionPatch = Partial<{
  readonly plan: PlanId;
  readonly interval: BillingInterval;
  readonly status: SubscriptionStatus;
  readonly seats: number;
  readonly currentPeriodStart: IsoTimestamp;
  readonly currentPeriodEnd: IsoTimestamp;
  readonly cancelAt: IsoTimestamp | null;
}>;

/** An invoice to issue alongside a change, for the period it covers. */
export interface InvoiceDraft {
  readonly amountCents: number;
  readonly periodStart: IsoTimestamp;
  readonly periodEnd: IsoTimestamp;
}

/**
 * Writes a subscription change and, when it is charged, the invoice for it, in
 * one transaction: a period never moves without its invoice, nor an invoice
 * exist without the period it bills. A non-positive amount issues nothing.
 *
 * Invoice numbers are sequential per workspace and are drawn inside the
 * transaction, so two writers cannot be handed the same number.
 */
export async function commitSubscription(
  orgId: OrgId,
  patch: SubscriptionPatch,
  invoice: InvoiceDraft | null,
): Promise<{ subscription: Subscription; invoice: Invoice | null }> {
  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Subscription for org ${orgId} not found`);
    const subscription = toSubscription(row);

    if (invoice === null || invoice.amountCents <= 0) {
      return { subscription, invoice: null };
    }

    const issued = tx
      .select({ total: count() })
      .from(invoices)
      .where(orgPredicate(invoices.orgId, orgId))
      .get();
    const stamp = toIsoTimestamp(new Date());
    const inserted = tx
      .insert(invoices)
      .values({
        id: newId(),
        orgId,
        number: formatInvoiceNumber((issued?.total ?? 0) + 1),
        amountCents: invoice.amountCents,
        currency: "usd",
        periodStart: invoice.periodStart,
        periodEnd: invoice.periodEnd,
        paidAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return { subscription, invoice: toInvoice(inserted) };
  });
}

function formatInvoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(6, "0")}`;
}

/**
 * Feeds the billing-renewal job; cross-tenant by design. Archived workspaces
 * are left out, and nothing is capped: every live workspace is returned.
 */
export async function listLiveSubscriptions(): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

