/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 *
 * What the change charges, and whether the period moves, is decided by
 * `planChangeFor`; the subscription row and any invoice are written together.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = current.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const change = planChangeFor(current, input, new Date());
  const { subscription, invoice } = await subscriptionRepo.commitSubscription(
    input.orgId,
    change.patch,
    change.invoice,
  );
  if (invoice) await publishInvoice(invoice);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

/**
 * Adding seats to a paid, active subscription charges the added seats for the
 * rest of the current period. Removing seats charges and credits nothing, and
 * a trial or the free plan charges nothing either.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const plan = current.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const now = new Date();
  const period = periodOf(current);
  const added = input.seats - current.seats;
  const charged =
    current.status === "active" && plan !== "free" && added > 0;
  const amountCents = charged
    ? prorateCents(
        fullChargeCents(plan, added, monthsIn(current.interval)),
        period,
        now,
      )
    : 0;

  const { subscription, invoice } = await subscriptionRepo.commitSubscription(
    input.orgId,
    { seats: input.seats },
    amountCents > 0 ? invoiceFor(period, amountCents) : null,
  );
  if (invoice) await publishInvoice(invoice);

  return subscription;
}

/**
 * Announces an issued invoice. The audit log and the owner's notification both
 * hang off this one event, so every invoice goes through here exactly once.
 */
export async function publishInvoice(invoice: Invoice): Promise<void> {
  await emit("billing.invoice_issued", {
    orgId: invoice.orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });
}

interface PlanChange {
  readonly patch: SubscriptionPatch;
  readonly invoice: InvoiceDraft | null;
}

/**
 * Decides what a plan change writes and charges. Pure, so the rules read in one
 * place:
 *
 * - A trial keeps its status and its period; the first invoice comes when it ends.
 * - Leaving the free plan starts a fresh period at `now`, invoiced in full.
 * - Between paid plans on an active subscription, the price increase per seat is
 *   charged for the rest of the current period. A downgrade or the same price
 *   charges nothing and the period stays put.
 * - Moving to the free plan charges nothing.
 */
function planChangeFor(
  current: Subscription,
  input: ChangePlanInput,
  now: Date,
): PlanChange {
  if (current.status === "trialing") {
    return {
      patch: { plan: input.plan, interval: input.interval },
      invoice: null,
    };
  }

  if (current.plan === "free" && input.plan !== "free") {
    const period = periodFrom(now, input.interval);
    const months = monthsIn(input.interval);
    return {
      patch: {
        plan: input.plan,
        interval: input.interval,
        status: "active",
        cancelAt: null,
        currentPeriodStart: toIsoTimestamp(period.start),
        currentPeriodEnd: toIsoTimestamp(period.end),
      },
      invoice: invoiceFor(
        period,
        fullChargeCents(input.plan, current.seats, months),
      ),
    };
  }

  const patch: SubscriptionPatch = {
    plan: input.plan,
    interval: input.interval,
    status: "active",
    cancelAt: null,
  };

  const months = monthsIn(current.interval);
  const increase = Math.max(
    0,
    fullChargeCents(input.plan, current.seats, months) -
      fullChargeCents(current.plan, current.seats, months),
  );
  if (current.status !== "active" || increase === 0) {
    return { patch, invoice: null };
  }

  const period = periodOf(current);
  const amountCents = prorateCents(increase, period, now);
  return {
    patch,
    invoice: amountCents > 0 ? invoiceFor(period, amountCents) : null,
  };
}

function periodOf(subscription: Subscription): PeriodSpan {
  return {
    start: new Date(subscription.currentPeriodStart),
    end: new Date(subscription.currentPeriodEnd),
  };
}

function invoiceFor(period: PeriodSpan, amountCents: number): InvoiceDraft {
  return {
    amountCents,
    periodStart: toIsoTimestamp(period.start),
    periodEnd: toIsoTimestamp(period.end),
  };
}

