/**
 * Moves subscriptions along: renews active ones whose period has ended, invoicing
 * every paid period, and ends cancellations whose date has come.
 *
 * Must call (do not reimplement): addMonths, fullChargeCents, monthsIn, emit, publishInvoice
 */
import { addMonths, fullChargeCents, monthsIn } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { publishInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Subscription } from "@/types/billing";

/** Where a cancelled workspace lands once its cancellation date has passed. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * Runs once an hour. Replay-safe: a renewed period ends after `now`, and a
 * cancelled workspace is no longer `canceled`, so a second pass at the same
 * instant finds nothing to do. Trials and past-due subscriptions are left to
 * their own flows.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listLiveSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const changed = await advance(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function advance(subscription: Subscription, now: Date): Promise<boolean> {
  if (subscription.status === "active") {
    return renewPeriods(subscription, now);
  }
  if (subscription.status === "canceled") {
    return endCancellation(subscription, now);
  }
  return false;
}

/**
 * Appends one period per elapsed interval until the period end lies after
 * `now`, so a subscription three months behind gets three consecutive periods.
 * Each paid period is invoiced for its full charge at the seat count now.
 */
async function renewPeriods(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  const months = monthsIn(subscription.interval);
  let periodEnd = new Date(subscription.currentPeriodEnd);
  if (periodEnd.getTime() > now.getTime()) return false;

  while (periodEnd.getTime() <= now.getTime()) {
    const start = periodEnd;
    const end = addMonths(start, months);
    const periodStart = toIsoTimestamp(start);
    const periodEndStamp = toIsoTimestamp(end);

    const charge =
      subscription.plan === FALLBACK_PLAN
        ? null
        : {
            amountCents: fullChargeCents(
              subscription.plan,
              subscription.seats,
              months,
            ),
            periodStart,
            periodEnd: periodEndStamp,
          };

    const { invoice } = await subscriptionRepo.commitSubscription(
      subscription.orgId,
      {
        currentPeriodStart: periodStart,
        currentPeriodEnd: periodEndStamp,
      },
      charge,
    );
    if (invoice) await publishInvoice(invoice);

    periodEnd = end;
  }

  return true;
}

/**
 * The workspace moves to the free plan as of the cancellation date, starting a
 * new monthly period there. No invoice: the paid period was already billed.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const cancelledAt = new Date(subscription.cancelAt);
  if (cancelledAt.getTime() > now.getTime()) return false;

  const stamp = toIsoTimestamp(cancelledAt);
  await subscriptionRepo.commitSubscription(
    subscription.orgId,
    {
      plan: FALLBACK_PLAN,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: stamp,
      currentPeriodEnd: toIsoTimestamp(addMonths(cancelledAt, 1)),
    },
    null,
  );

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: stamp,
    from: subscription.plan,
    to: FALLBACK_PLAN,
  });

  return true;
}

