  cleanup();
});

describe("period arithmetic", () => {
  it("clamps to the last day of a shorter month and carries the clamp forward", () => {
    const jan31 = new Date("2026-01-31T10:30:00.000Z");
    const feb = addMonths(jan31, 1);
    expect(feb.toISOString()).toBe("2026-02-28T10:30:00.000Z");
    expect(addMonths(feb, 1).toISOString()).toBe("2026-03-28T10:30:00.000Z");
  });

  it("moves an annual period by a year, clamping 29 February", () => {
    expect(addMonths(new Date("2028-02-29T00:00:00.000Z"), 12).toISOString()).toBe(
      "2029-02-28T00:00:00.000Z",
    );
  });

  it("counts a started day as a whole day left when prorating", () => {
    const period = {
      start: new Date("2026-06-01T00:00:00.000Z"),
      end: new Date("2026-07-01T00:00:00.000Z"),
    };
    // 14 days and 22 hours left: 15 days of the 30 in the period.
    const now = new Date("2026-06-16T02:00:00.000Z");
    expect(prorateCents(3_000, period, now)).toBe(1_500);
    expect(prorateCents(3_000, period, period.end)).toBe(0);
  });
});

describe("the renewal job", () => {
  it("renews a lapsed subscription once per elapsed interval and invoices each paid period", async () => {
    const tenant = await createTenant("renewal-catch-up", "starter");
    await subscriptionRepo.commitSubscription(
      tenant.org.id,
      {
        status: "active",
        currentPeriodStart: toIsoTimestamp("2025-12-31T00:00:00.000Z"),
        currentPeriodEnd: toIsoTimestamp("2026-01-31T00:00:00.000Z"),
      },
      null,
    );

    const now = new Date("2026-04-15T00:00:00.000Z");
    await runBillingRenewalJob(now);

    const invoices = await billingService.listInvoices(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-03-28T00:00:00.000Z",
      "2026-02-28T00:00:00.000Z",
      "2026-01-31T00:00:00.000Z",
    ]);
    expect(invoices.every((invoice) => invoice.amountCents === 900)).toBe(true);
    expect(invoices.map((invoice) => invoice.number)).toEqual([
      "INV-000003",
      "INV-000002",
      "INV-000001",
    ]);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2026-03-28T00:00:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-04-28T00:00:00.000Z");
  });

  it("is replay-safe: a second run at the same instant changes nothing", async () => {
    const tenant = await createTenant("renewal-replay", "starter");
    await subscriptionRepo.commitSubscription(
      tenant.org.id,
      {
        status: "active",
        currentPeriodStart: toIsoTimestamp("2026-04-01T00:00:00.000Z"),
        currentPeriodEnd: toIsoTimestamp("2026-05-01T00:00:00.000Z"),
      },
      null,
    );

    const now = new Date("2026-05-02T00:00:00.000Z");
    const first = await runBillingRenewalJob(now);
    const second = await runBillingRenewalJob(now);

    expect(first.failed).toBe(0);
    expect(second.processed).toBe(0);

    const invoices = await billingService.listInvoices(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(invoices).toHaveLength(1);
  });

  it("ends a cancellation on its date and moves the workspace to free without an invoice", async () => {
    const tenant = await createTenant("renewal-cancel", "growth");
    await subscriptionRepo.cancelSubscription(
      tenant.org.id,
      toIsoTimestamp("2026-05-01T00:00:00.000Z"),
    );

    const changes: unknown[] = [];
    const off: Unsubscribe = subscribe("billing.plan_changed", (payload) => {
      changes.push(payload);
    });

    await runBillingRenewalJob(new Date("2026-04-30T23:00:00.000Z"));
    expect(changes).toHaveLength(0);
    expect(
      (await subscriptionRepo.findSubscription(tenant.org.id))?.status,
    ).toBe("canceled");

    await runBillingRenewalJob(new Date("2026-05-02T00:00:00.000Z"));
    off();

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });
    expect(changes).toHaveLength(1);
    expect(changes[0]).toMatchObject({ orgId: tenant.org.id, from: "growth", to: "free" });

    const invoices = await billingService.listInvoices(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(invoices).toHaveLength(0);
  });
});

