      periodEnd: "2026-07-01T00:00:00.000Z",
    });
  });

  it("charges the price increase for a plan change between paid plans", async () => {
    const tenant = await createTenant("prorate-plan", "starter");
    await subscriptionRepo.commitSubscription(
      tenant.org.id,
      {
        status: "active",
        currentPeriodStart: toIsoTimestamp("2026-06-01T00:00:00.000Z"),
        currentPeriodEnd: toIsoTimestamp("2026-07-01T00:00:00.000Z"),
      },
      null,
    );
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-16T00:00:00.000Z"));

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    // (1_900 - 900) per seat, one seat, half of the period left.
    const invoices = await billingService.listInvoices(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(500);
    expect(
      (await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd,
    ).toBe("2026-07-01T00:00:00.000Z");
  });

  it("keeps a trial and its period when a plan is chosen, and charges nothing", async () => {
    const tenant = await createTenant("trial-plan-choice", "starter");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);

    const after = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });

    expect(after).toMatchObject({
      plan: "growth",
      interval: "annual",
      status: "trialing",
      currentPeriodStart: before?.currentPeriodStart,
      currentPeriodEnd: before?.currentPeriodEnd,
    });
    const invoices = await billingService.listInvoices(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(invoices).toHaveLength(0);
  });
});
